/* ================================================================
 * Depth Shader (encode linear depth into RGBA8)
 * ================================================================ */

static const char *DEPTH_VS =
    "attribute vec3 a_pos;\n"
    "attribute vec2 a_uv;\n"
    "uniform mat4 u_mvp;\n"
    "uniform float u_znear;\n"
    "uniform float u_zfar;\n"
    "varying float v_depth;\n"
    "varying vec2 v_uv;\n"
    "void main() {\n"
    "  gl_Position = u_mvp * vec4(a_pos, 1.0);\n"
    "  float linear = (gl_Position.w - u_znear) / (u_zfar - u_znear);\n"
    "  v_depth = clamp(linear, 0.0, 1.0);\n"
    "  v_uv = a_uv;\n"
    "}\n";

static const char *DEPTH_FS =
    "precision highp float;\n"
    "varying float v_depth;\n"
    "varying vec2 v_uv;\n"
    "uniform sampler2D u_albedo_tex;\n"
    "uniform int u_use_texture;\n"
    "const float ALPHA_CUTOFF = 0.5;\n"
    "void main() {\n"
    "  if (u_use_texture != 0) {\n"
    "    float alpha = texture2D(u_albedo_tex, v_uv).a;\n"
    "    if (alpha < ALPHA_CUTOFF) {\n"
    "      discard;\n"
    "    }\n"
    "  }\n"
    "  vec4 enc = vec4(1.0, 255.0, 65025.0, 16581375.0) * v_depth;\n"
    "  enc = fract(enc);\n"
    "  enc -= enc.yzww * vec4(1.0/255.0, 1.0/255.0, 1.0/255.0, 0.0);\n"
    "  gl_FragColor = enc;\n"
    "}\n";


